def canonical(a):
 def field(s):return str(len(s.encode()))+':'+s
 return 'tuple-v1:1;'+field(a['cue'])+field(a['answer'])+str(len(a['distractors']))+';'+''.join(field(s) for s in a['distractors'])
def main():
 raw=PACK.read_bytes();p=json.loads(raw)
 if any(i['id']=='u29-i-adjective-form-1' for i in p['items']):print('Already repaired; evidence unchanged');return
 obj='obj-u29-short-adjective';unit=p['units'][28];assert unit['number']==29
 source=ROOT/'catalog/sources/units-26-30/wikipedia/russian-grammar-1369617627.txt';text=source.read_text()
